function validate(input) {
  const [{ Tweets = [] }] = input;
  const ids = new Set(), spelling = new Map();
  for (const [user, id, date, tweet] of Tweets) {
    if (id === null) return 'Every tweet needs a tweet_id.';
    if (ids.has(id)) return `tweet_id ${id} appears twice.`;
    ids.add(id);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date ?? '')) return `Tweet ${id} needs a date like 2024-02-01.`;
    if (typeof tweet !== 'string') return `Tweet ${id} needs its text.`;
    if (tweet.length > 100) return `Tweet ${id} is longer than 100 characters.`;
    if (/[\t\r\n]/.test(tweet)) return `Tweet ${id} may only separate words with spaces.`;
    const own = new Set();
    for (const word of tweet.split(' ')) {
      if (!word.includes('#')) continue;
      if (!/^#[A-Za-z0-9]+$/.test(word)) return `In tweet ${id}, "${word}" is not a hashtag of letters and digits standing alone.`;
      const lower = word.toLowerCase();
      if (own.has(lower)) return `Tweet ${id} repeats ${word}.`;
      own.add(lower);
      if (spelling.has(lower) && spelling.get(lower) !== word) return `Hashtags ${spelling.get(lower)} and ${word} differ only in case.`;
      spelling.set(lower, word);
    }
  }
  return null;
}

