function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const tags = small
    ? ['#HappyDay', '#TechLife', '#WorkLife', '#Nature', '#FeelGood', '#Travel']
    : Array.from({ length: 40 }, (_, i) => `#Topic${i}`);
  const dates = ['2024-02-01', '2024-02-05', '2024-02-14', '2024-02-29', '2024-01-31', '2024-03-01', '2023-02-10'];
  const words = ['Enjoying', 'the', 'day.', 'Great', 'vibes!', 'New', 'post', 'today', 'with', 'friends'];
  const count = small ? Math.floor(rand() * 9) : 2000;
  const Tweets = [];
  for (let i = 0; i < count; i++) {
    const date = small ? pick(dates) : `2024-${pick(['01', '02', '02', '02', '03'])}-${String(1 + Math.floor(rand() * 29)).padStart(2, '0')}`;
    const parts = Array.from({ length: 1 + Math.floor(rand() * 4) }, () => pick(words));
    // Up to three distinct hashtags, each dropped at a random position among the words.
    const pool = tags.slice();
    const k = Math.floor(rand() * 4);
    for (let j = 0; j < k; j++) {
      const at = j + Math.floor(rand() * (pool.length - j));
      [pool[j], pool[at]] = [pool[at], pool[j]];
      parts.splice(Math.floor(rand() * (parts.length + 1)), 0, pool[j]);
    }
    Tweets.push([1 + Math.floor(rand() * (small ? 4 : 300)), 100 + i, date, parts.join(' ')]);
  }
  return [{ Tweets }];
}
